<div class="page-heading"><div><div class="breadcrumb-line">Home <span>&rsaquo;</span> Stock / Parts <span>&rsaquo;</span> <b><?= $section==='stock-low'?'Low Stock':'Stock List' ?></b></div><h1><?= e($title) ?></h1><p>Manage and track all stock items and parts.</p></div><div class="estimate-heading-actions"><a class="btn btn-light" href="index.php?page=admin&amp;section=stock-purchases">Stock Purchases</a><a class="btn btn-light" href="index.php?page=admin&amp;section=stock-restock">+ Restock Item</a><a class="btn btn-danger" href="index.php?page=admin&amp;section=stock-add">+ Add New Item</a></div></div><div class="admin-panel stock-list"><div class="panel-heading"><h2><?= $section==='stock-low'?'Low Stock Items':'Stock / Parts List' ?></h2><span><?= count($rows) ?> items</span></div><div class="table-responsive"><table class="table admin-table"><thead><tr><th>Part No.</th><th>Part Name</th><th>Category</th><th>Brand</th><th>Unit</th><th>Average Cost</th><th>Selling Price</th><th>Stock Qty</th><th>Min. Level</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="11" class="empty-table">No stock items found.</td></tr><?php else: foreach($rows as $row): $status=(float)$row['stock_qty']<=0?'Out of Stock':((float)$row['stock_qty']<=(float)$row['reorder_level']?'Low Stock':'In Stock'); ?><tr><td><?= e($row['part_code']) ?></td><td><strong><?= e($row['part_name']) ?></strong></td><td><?= e($row['category']?:'-') ?></td><td><?= e($row['brand']?:'-') ?></td><td><?= e($row['unit']) ?></td><td><?= number_format((float)($row['average_cost']?:$row['buying_price']),2) ?></td><td><?= number_format((float)$row['selling_price'],2) ?></td><td><strong><?= number_format((float)$row['stock_qty'],2) ?></strong></td><td><?= number_format((float)$row['reorder_level'],2) ?></td><td><span class="stock-status"><?= e($status) ?></span></td><td><div class="action-links employee-actions"><a href="index.php?page=admin&amp;section=stock-view&amp;id=<?= (int)$row['id'] ?>" title="View">&#128065;</a><a href="index.php?page=admin&amp;section=stock-restock&amp;id=<?= (int)$row['id'] ?>" title="Restock">+</a><form method="post" action="index.php?page=admin&amp;section=stock-delete&amp;id=<?= (int)$row['id'] ?>" onsubmit="return confirm('Remove this stock item?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button type="submit" title="Delete">&#128465;</button></form></div></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
